//! Nonfinancial activity within one UTC calendar month.
use chrono::{DateTime, Datelike, Months, Utc};
use super::{funder::{FunderId, FunderKind}, parliament_member::MemberId};
use std::num::NonZeroUsize;

/// Half-open UTC calendar month.
#[derive(Clone, Debug)]
pub struct RegistrationMonth { start: DateTime<Utc>, end: DateTime<Utc> }
impl RegistrationMonth {
    /// Selects the complete calendar month containing the supplied instant.
    #[must_use]
    pub fn containing(now: DateTime<Utc>) -> Self {
        let start = now.date_naive().with_day(1).expect("day one exists").and_hms_opt(0, 0, 0).expect("midnight exists").and_utc();
        let end = start.checked_add_months(Months::new(1)).expect("following calendar month exists");
        Self { start, end }
    }
    /// Inclusive lower boundary.
    #[must_use]
    pub const fn start(&self) -> DateTime<Utc> { self.start }
    /// Exclusive upper boundary.
    #[must_use]
    pub const fn end(&self) -> DateTime<Utc> { self.end }
    /// Whether a registration belongs to this month.
    #[must_use]
    pub fn includes(&self, date: DateTime<Utc>) -> bool { date >= self.start && date < self.end }
}
/// Recipient identity.
#[derive(Clone, Debug)]
pub struct UpdatedMember {
    /// Parliament identity.
    pub id: MemberId,
    /// Stored name.
    pub name: String,
}
/// Canonical company identity.
