        "10000000-0000-0000-0000-000000000001"
    );
    assert!(
        updates
            .companies
            .iter()
            .any(|row| row.identity.name == "Trust root")
    );
    assert!(
        updates
            .companies
            .iter()
            .any(|row| row.identity.name == "Unclassified funder")
    );
