import type { CategoryWheelOption } from "./ui";

export interface EntityUpdate {
  id: string;
  name: string;
  declarationCount: number;
  latestRegistration: string;
}
export interface MonthlyUpdates {
  monthStart: string;
  monthEnd: string;
  members: EntityUpdate[];
  companies: EntityUpdate[];
}
export function updateMonth(value: string): string {
  return new Intl.DateTimeFormat("en-GB", {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(value));
}
export function updateDate(value: string): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(value));
}

export type UpdateCategory = "members" | "companies";
export const updateCategories = {
  members: {
    id: "members",
    prefix: "members",
    kind: "MP",
    label: "MPs",
    icon: "parliament",
    accent: "member",
    path: "M138 8 A130 130 0 0 0 8 138 L98 138 A40 40 0 0 1 138 98 Z",
    rimPath: "M138 8 A130 130 0 0 0 8 138",
    left: 0,
    top: 0,
    x: 73,
    y: 73,
  },
  companies: {
    id: "companies",
    prefix: "funders",
    kind: "Company",
    label: "Companies",
    icon: "building",
    accent: "funder",
    path: "M4 134 A130 130 0 0 0 134 4 L44 4 A40 40 0 0 1 4 44 Z",
    rimPath: "M4 134 A130 130 0 0 0 134 4",
    left: 142,
    top: 142,
    x: 54,
    y: 55,
  },
} satisfies Record<
  UpdateCategory,
  CategoryWheelOption<UpdateCategory> & { prefix: string; kind: string }
>;
<script lang="ts">
  import AppShell from "../../AppShell.svelte";
  import {
    ResultRow,
    CategoryWheel,
    Notice,
    IconIndicator,
  } from "../../lib/ui";
  import {
    updateMonth,
    updateDate,
    updateCategories,
    type UpdateCategory,
  } from "../../lib/updates";
  import type { PageData } from "./$types";
  let { data }: { data: PageData } = $props();
  let selected = $state<UpdateCategory>("members");
  const rows = $derived(data.updates?.[selected] ?? []);
  const category = $derived(updateCategories[selected]);
</script>

<svelte:head><title>Updates | Exposed</title></svelte:head>
<AppShell target="updates" current="updates">
  <main id="updates" tabindex="-1">
    {#if data.updates}
      <div class="updates-intro">
        <div>
          <h1>Updates</h1>
          <p class="month">
            <time datetime={data.updates.monthStart.slice(0, 7)}
              >{updateMonth(data.updates.monthStart)}</time
            >
          </p>
        </div>
        <div class="selector">
          <CategoryWheel
            options={Object.values(updateCategories)}
            size={220}
            {selected}
            label="Updates category"
            onselect={(category) => (selected = category)}
          />
        </div>
      </div>
      {#key selected}
        <div class="board" style={`--accent: var(--accent-${category.accent})`}>
          {#if rows.length}
            <ul class="results-list" aria-label={`${category.label} updates`}>
              {#each rows as row (row.id)}
                <ResultRow>
                  <IconIndicator icon={category.icon} label={category.kind} />
                  <div class="entity-text">
                    <a
                      class="entity-name"
                      href={`/${category.prefix}/${row.id}`}>{row.name}</a
                    >
                    <span class="entity-alias"
                      >{row.declarationCount} declaration{row.declarationCount ===
                      1
                        ? ""
                        : "s"}</span
                    >
                  </div>
                  <time class="registered" datetime={row.latestRegistration}
                    >{updateDate(row.latestRegistration)}</time
                  >
                </ResultRow>
              {/each}
            </ul>
          {:else}<p class="empty">No declarations found.</p>{/if}
        </div>
      {/key}
    {:else}<h1>Updates</h1>
      <Notice role="alert">{data.error}</Notice>{/if}
  </main>
</AppShell>

<style>
  .month {
    margin: var(--space-2) 0;
    color: var(--muted);
    font-size: var(--text-heading);
    line-height: 1.5;
  }
  .updates-intro {
    display: flex;
